//! Same process, original owner locks/worker guards and signed durable ledger.
//! No real providers, copied profiles, new scheduler or external effects.
use super::{admission::{Review,Budget,Payment,Denial},admission_tests::Fixture,authority::{Authority,Failure},authority_store::Fault as GrantFault,deterministic_runtime_tests::{draft_with,queued,evidence},lease_controller::{Controller,Pending,Owned,Validity},leases::DrainOutcome,model::*,native_completion_tests::send,reconciliation_tests::inventory,store::{Store,Fault as GoalFault,nonce}};
use crate::chat::Chat;
use std::{fs,sync::Arc};
struct Env{f:Fixture,a:Authority,g:Record,p:Pending,o:Owned,main:Chat}
fn now()->u64{crate::assistant_memory::now()}
impl Env{
 fn new(provider:&str)->Self{let f=Fixture::new();let a=Authority::ensure(&f.path.join("authority")).unwrap();let draft=draft_with(&f,provider,vec![super::criteria::NATIVE_MESSAGE_CRITERION.into()],2);let q=queued(&f,&a,&draft);let main=Chat::persistent(f.path.join("native-main.json"));let(g,p,o)=claim(&f,&a,&q,&main);Self{f,a,g,p,o,main}}
 fn store(&self)->Store{Store::existing_verified(&self.f.path.join("goals"),&self.f.path.join("authority")).unwrap().unwrap()}
 fn pause(&self)->Record{super::authority_store::mutate_with_authority(&self.store(),&self.f.path.join("authority"),&self.g.id,&self.g.spec.owner.pet_id,&self.g.revision,nonce().unwrap(),Action::Pause,now()).unwrap().record}
 fn close(&self,g:&Record,outcome:DrainOutcome)->Record{let d=self.o.drain(outcome).unwrap();let r=self.store().drain_owned(&self.a,&d,now()).unwrap();assert_ne!(r.status,CommitStatus::Uncertain);if d.confirmed(){self.p.hold().release_drained(&d).unwrap();}let current=self.store().read(&g.id,&g.spec.owner.pet_id).unwrap();assert_eq!(current.revision,r.record.revision);current}
}
fn claim(f:&Fixture,a:&Authority,g:&Record,main:&Chat)->(Record,Pending,Owned){let at=now();let p=Controller::new().unwrap().prepare(g,&f.path.join("authority"),&f.path.join("contexts"),main,&evidence(g,at),nonce().unwrap(),at,Arc::new(|_,_,_|Validity::Current)).unwrap();let(r,o)=p.claim(&f.store(),a,&evidence(g,at),at).unwrap();(r.record,p,o.unwrap())}
fn review(e:&Env,g:&Record,tools:u16)->Review{let at=now();let(source,captured)=e.store().prepare_continuation_review(&e.f.path.join("authority"),&g.id,&g.spec.owner.pet_id,&g.revision,at,false).unwrap().unwrap();Review::prepare_deterministic_continuation(&source,evidence(&source,at),Budget{deadline_at:at+120_000,max_model_calls:0,max_tool_calls:tools,max_output_bytes:32768,max_tokens:None,max_cost_micros:None,payment:Payment::RuntimeOnly},captured,nonce().unwrap(),nonce().unwrap(),at).unwrap()}
fn continue_goal(e:&Env,g:&Record,tools:u16)->Record{let prepared=review(e,g,tools);let at=now();let mut approved=prepared.approve(g,evidence(g,at),at).unwrap();let a=approved.take_native_authority().unwrap();let cert=a.certify(&approved,g,at).unwrap();e.store().enqueue_certified(&cert,at).unwrap().record}
fn grant(e:&Env)->Vec<u8>{fs::read(e.f.path.join("authority").join(format!("{}.json",e.g.admissions[0].spec.decision_id))).unwrap()}
#[test]fn native_drain_continuation_uses_the_same_live_backend_and_only_charges_missing_messages_for_all_pets(){
 for provider in ["codex","copilot","antigravity","ollama","lmstudio","openai","integration_spotify"]{
  let e=Env::new(provider);send(&e.g,&e.o,0);let stopped=e.pause();let closed=e.close(&stopped,DrainOutcome::Confirmed);assert_eq!(closed.state,State::Paused);assert_eq!(closed.schema_version,19);assert_eq!(closed.native_drains.len(),1);let r=&closed.native_drains[0];assert!(r.confirmed&&r.continuable());assert!(!e.o.current(now()));let old=grant(&e);let native:serde_json::Value=serde_json::from_slice(&old).unwrap();assert_eq!(native["body"]["schemaVersion"],13);assert_eq!(native["body"]["runtimeOwner"]["process"]["pid"],std::process::id());assert!(native["body"].get("recovery").is_none());
  let proposal=review(&e,&closed,1).proposal();let c=proposal.continuation.as_ref().unwrap();assert_eq!(c.schema_version,4);assert!(c.closure.is_none());assert_eq!(c.drain.as_ref(),Some(r));assert_eq!(c.charge.tool_calls,1);assert_eq!(c.charge.model_calls,0);assert_eq!(c.native.as_ref().unwrap().receipts.len(),1);assert!(proposal.resolved_model.is_empty());let q=continue_goal(&e,&closed,1);assert_eq!(q.schema_version,20);assert_eq!(q.admissions[1].spec.schema_version,7);
  let at=now();assert_eq!(Controller::new().unwrap().prepare(&q,&e.f.path.join("authority"),&e.f.path.join("contexts"),&e.main,&evidence(&q,at),nonce().unwrap(),at,Arc::new(|_,_,_|Validity::Current)).err(),Some(Error::Busy));
  // The service retires both original Entry references after durable closure.
  // The exclusive context writer is intentionally retained until that drop.
  let old_lease=e.o.lease().id.clone();let old_path=e.f.path.join("authority").join(format!("{}.json",e.g.admissions[0].spec.decision_id));assert!(!e.p.hold().occupies_slot());let Env{f,a,p:old_pending,o:old_owner,main,..}=e;drop(old_pending);drop(old_owner);
  let(g,p,o)=claim(&f,&a,&q,&main);let store=Store::existing_verified(&f.path.join("goals"),&f.path.join("authority")).unwrap().unwrap();assert_ne!(o.lease().id,old_lease);assert!(p.hold().occupies_slot());send(&g,&o,1);let result=o.verify_native_goal(&store,&g).unwrap();assert!(result.report.criteria_verified);assert!(!result.recipient_execution_verified);let done=result.completion.unwrap().record;assert_eq!(done.state,State::Completed);assert_eq!(done.schema_version,20);let d=o.drain(DrainOutcome::Confirmed).unwrap();store.drain_owned(&a,&d,now()).unwrap();p.hold().release_drained(&d).unwrap();let h=store.history(&f.path.join("authority"),&done.id,&done.spec.owner.pet_id,&done.revision,now()).unwrap();assert!(h.accounting_complete&&h.source_consistent);let charge=h.cumulative_charge.unwrap();assert_eq!(charge.tool_calls,2);assert_eq!(charge.model_calls,0);assert_eq!(fs::read(old_path).unwrap(),old);
 }
}
#[test]fn native_drain_cannot_publish_or_release_a_resource_while_the_original_worker_is_alive(){
 let e=Env::new("ollama");let worker=e.o.readiness_worker(now()).unwrap();let before=inventory(&e.f.path);assert_eq!(e.o.drain(DrainOutcome::Confirmed).err(),Some(Error::Busy));assert_eq!(inventory(&e.f.path),before);assert!(e.p.hold().occupies_slot());assert!(!e.o.current(now()));drop(worker);let closed=e.close(&e.g,DrainOutcome::Confirmed);assert_eq!(closed.state,State::RecoveryRequired);assert!(closed.native_drains[0].confirmed);assert!(!e.p.hold().occupies_slot());
}
#[test]fn native_drain_uncertain_cancelled_and_closed_without_a_native_seal_do_not_become_confirmed_sources(){
 for outcome in [DrainOutcome::Uncertain,DrainOutcome::Confirmed]{
  let e=Env::new("openai");send(&e.g,&e.o,0);let source=if outcome==DrainOutcome::Confirmed{super::authority_store::mutate_with_authority(&e.store(),&e.f.path.join("authority"),&e.g.id,&e.g.spec.owner.pet_id,&e.g.revision,"cancel-native-source".into(),Action::Cancel,now()).unwrap().record}else{e.g.clone()};let closed=e.close(&source,outcome);let before=inventory(&e.f.path);assert!(matches!(e.store().prepare_continuation_review(&e.f.path.join("authority"),&closed.id,&closed.spec.owner.pet_id,&closed.revision,now(),false).unwrap(),Err(Denial::RecoveryNotClosed)));assert_eq!(inventory(&e.f.path),before);assert_eq!(closed.native_drains[0].confirmed,outcome==DrainOutcome::Confirmed);
 }
 let e=Env::new("codex");let stopped=e.pause();let row=&stopped.admissions[0];e.a.finish(&row.spec,row.proof.as_ref().unwrap(),e.o.lease(),false,row.stop_reason,now()).unwrap();let mut projected=stopped.clone();projected.drained(e.o.lease(),true,now(),nonce().unwrap(),nonce().unwrap()).unwrap();let p=e.f.path.join("goals").join(format!("{}.json",projected.id));fs::write(p,serde_json::to_vec(&projected).unwrap()).unwrap();let before=inventory(&e.f.path);assert!(matches!(e.store().prepare_continuation_review(&e.f.path.join("authority"),&projected.id,&projected.spec.owner.pet_id,&projected.revision,now(),false).unwrap(),Err(Denial::RecoveryNotClosed)));assert_eq!(inventory(&e.f.path),before);
}
#[test]fn native_drain_grant_and_goal_publication_faults_reuse_the_exact_closure_and_budget(){
 for fault in [GrantFault::BeforeGrantPublish,GrantFault::AfterGrantPublish]{
  let mut e=Env::new("copilot");send(&e.g,&e.o,0);let stopped=e.pause();let d=e.o.drain(DrainOutcome::Confirmed).unwrap();e.a.fault=fault;assert!(e.store().drain_owned(&e.a,&d,now()).is_err());let saved=d.with_native_drain(|c|Ok(c.clone().unwrap())).unwrap();assert!(e.p.hold().occupies_slot());e.a.fault=GrantFault::None;let r=e.store().drain_owned(&e.a,&d,now()).unwrap();assert_eq!(r.record.native_drains[0],saved.reference);assert_eq!(e.a.native_drain(&r.record).unwrap().unwrap(),saved);let h=e.store().history(&e.f.path.join("authority"),&r.record.id,&r.record.spec.owner.pet_id,&r.record.revision,now()).unwrap();assert!(h.accounting_complete&&h.source_consistent&&h.pending_artifacts==0);assert_eq!(h.cumulative_charge.unwrap().tool_calls,1);let before=inventory(&e.f.path);let ack=e.store().ack_native_drain(&e.f.path.join("authority"),&stopped.id,&stopped.spec.owner.pet_id,&e.o.lease().id,&stopped.revision).unwrap();assert_eq!(ack.record.revision,r.record.revision);assert_eq!(inventory(&e.f.path),before);e.p.hold().release_drained(&d).unwrap();
 }
 for fault in [GoalFault::BeforePublish,GoalFault::AfterPublish]{
  let e=Env::new("integration_spotify");send(&e.g,&e.o,0);let stopped=e.pause();let d=e.o.drain(DrainOutcome::Confirmed).unwrap();let mut store=e.store();store.fault=fault;let _=store.drain_owned(&e.a,&d,now());assert!(e.p.hold().occupies_slot());let sealed=e.a.native_drain(&stopped).unwrap().unwrap();let bytes=grant(&e);drop(d);drop(store);let restored=e.store();let ack=restored.ack_native_drain(&e.f.path.join("authority"),&stopped.id,&stopped.spec.owner.pet_id,&e.o.lease().id,&stopped.revision).unwrap();assert_eq!(ack.record.native_drains[0],sealed.reference);assert_eq!(grant(&e),bytes);let frozen=inventory(&e.f.path);assert!(restored.ack_native_drain(&e.f.path.join("authority"),&stopped.id,"agent_codex",&e.o.lease().id,&stopped.revision).is_err());assert!(restored.ack_native_drain(&e.f.path.join("authority"),&stopped.id,&stopped.spec.owner.pet_id,&nonce().unwrap(),&stopped.revision).is_err());assert_eq!(inventory(&e.f.path),frozen);
 }
}
#[test]fn native_drain_stop_after_an_unpublished_close_supersedes_only_the_old_audit_preparation(){
 let mut e=Env::new("ollama");send(&e.g,&e.o,0);let stopped=e.pause();let d=e.o.drain(DrainOutcome::Confirmed).unwrap();e.a.fault=GrantFault::BeforeGrantPublish;assert!(e.store().drain_owned(&e.a,&d,now()).is_err());let old=d.with_native_drain(|c|Ok(c.clone().unwrap())).unwrap();e.a.fault=GrantFault::None;
 let cancelled=super::authority_store::mutate_with_authority(&e.store(),&e.f.path.join("authority"),&stopped.id,&stopped.spec.owner.pet_id,&stopped.revision,"cancel-while-native-close-staged".into(),Action::Cancel,now()).unwrap().record;assert_eq!(cancelled.state,State::Stopping);let r=e.store().drain_owned(&e.a,&d,now()).unwrap();assert_eq!(r.record.state,State::Cancelled);let seal=e.a.native_drain(&r.record).unwrap().unwrap();assert_eq!(seal.superseded_preparations.len(),1);assert_eq!(seal.superseded_preparations[0].reference,old.reference);assert_ne!(seal.reference.id,old.reference.id);let h=e.store().history(&e.f.path.join("authority"),&r.record.id,&r.record.spec.owner.pet_id,&r.record.revision,now()).unwrap();assert!(h.pending_artifacts==0&&h.accounting_complete);assert_eq!(h.cumulative_charge.unwrap().tool_calls,1);
}
#[test]fn native_drain_forged_outcome_or_missing_signed_fact_is_not_a_continuation_or_authority(){
 let e=Env::new("antigravity");let closed=e.close(&e.g,DrainOutcome::Uncertain);let file=e.f.path.join("goals").join(format!("{}.json",closed.id));let bytes=fs::read(&file).unwrap();let mut forged=closed.clone();forged.native_drains[0].confirmed=true;let at=forged.native_drains[0].target_sequence as usize-1;forged.events[at].fingerprint=fingerprint(&forged.native_drains[0]).unwrap();forged.validate().unwrap();fs::write(&file,serde_json::to_vec(&forged).unwrap()).unwrap();assert!(e.store().read(&closed.id,&closed.spec.owner.pet_id).is_err());fs::write(&file,bytes).unwrap();let p=e.f.path.join("authority").join(format!("{}.json",e.g.admissions[0].spec.decision_id));fs::remove_file(p).unwrap();assert!(e.store().read(&closed.id,&closed.spec.owner.pet_id).is_err());assert_eq!(e.o.drain(DrainOutcome::Uncertain).unwrap().confirmed(),false);
}
